from taf.rfrl.csv4all.resources.utilities.exceptions import MainExceptionClass


class GivenNodeIdNotFoundError(Exception):
    """ Raised when given node ID wasn't found in configured nodes"""
    pass


class DisallowedIMSAlarmsDetected(Exception):
    def __init__(self, detected_alarms):
        self.alarms = detected_alarms


class NodeInformationNotProvidedError(Exception):
    """ Raised when given recovery method doesn't end with success"""

    def __init__(self):
        super().__init__("Not Enough data to create Node Object!\n"
                         "Please either provide Testline object or node_vm and node_mrbts_id parameters!")


class WrongSwVersion(Exception):
    """ Raised when given sw differs from active one"""
    pass


class SwActivationError(Exception):
    """ Raised when sw activation failed"""
    pass


class SwDownloadError(Exception):
    """ Raised when sw download failed"""
    pass


class SwconfigFileError(Exception):
    """ Raised when swconfig is not found on node or mandatory flag: 0x10041 doesn't exist"""
    pass


class VerificationBtsFailed(Exception):
    """ Raised when Bts state is not as expected"""
    pass


class ValidationScfFailed(Exception):
    """ Raised when validation scf fail"""
    pass


class SuspiciousPrintsFoundError(Exception):
    """ Raised when suspicious prints found during checking syslog"""
    pass


class BlackboxVerificationFailed(Exception):
    """ Raised when suspicious prints found during checking syslog"""
    pass


class HWFMigrationError(MainExceptionClass):
    """ Error when HWF migration after upgrade has not expected state """
    pass


class FallbackFaultNotAppear(Exception):
    """ Error when Fallback fault not appear """
    pass


class MplaneVerificationFailed(Exception):
    """ Error when access to mplane has failed """
    pass


class WrongAMFStatus(Exception):
    """ Error when status of AMF is not Active """
    pass
